// Des: Unit tests for HTTP gate, parsing, static guard
// Flo: build Requ > run gate or helper > assert verdict, text, null
// I/O: Host, Origin, Sec-Fetch values, paths > pass or fail
// ===================================================================
const std = @import("std"); const http = @import("sv-main-http.zig");
const tszz = std.testing; const Requ = http.Requ; const Gate = http.Gate; const gate = http.gate;
test "hostOk pins the loopback names, closing DNS rebinding" { try tszz.expect(http.hostOkay("localhost")); try tszz.expect(http.hostOkay("127.0.0.1:3030")); try tszz.expect(http.hostOkay("[::1]:3030")); try tszz.expect(!http.hostOkay("attacker.example")); try tszz.expect(!http.hostOkay("evil.com:3030")); try tszz.expect(!http.hostOkay("localhost.evil.com")); try tszz.expect(!http.hostOkay("127.0.0.1.evil.com")); try tszz.expect(!http.hostOkay("localhost:80a")); try tszz.expect(!http.hostOkay(null)); try tszz.expect(http.hostOkay("LOCALHOST:3030")); try tszz.expect(!http.hostOkay("127.0.0.1.:3030")); }
test "gate: same-origin only, fetch metadata, non-browser clients pass" { const base = Requ{ .meth = "POST", .path = "/run", .host = "127.0.0.1:3030" }; try tszz.expectEqual(Gate.okay, gate(base, false)); var uizz = base; uizz.orig = "http://127.0.0.1:3030"; uizz.secz_site = "same-origin"; try tszz.expectEqual(Gate.okay, gate(uizz, false)); var othe = base; othe.orig = "http://localhost:5173"; try tszz.expectEqual(Gate.orig, gate(othe, false)); var othe_port = base; othe_port.orig = "http://127.0.0.1:3031"; try tszz.expectEqual(Gate.orig, gate(othe_port, false)); var imgz = Requ{ .meth = "GET", .path = "/open-mini", .host = "127.0.0.1:3030", .secz_site = "cross-site", .secz_mode = "no-cors" }; try tszz.expectEqual(Gate.fetc_site, gate(imgz, false)); imgz.secz_site = "same-site"; try tszz.expectEqual(Gate.fetc_site, gate(imgz, false)); const navi = Requ{ .meth = "GET", .path = "/", .host = "127.0.0.1:3030", .secz_site = "cross-site", .secz_mode = "navigate" }; try tszz.expectEqual(Gate.okay, gate(navi, true)); try tszz.expectEqual(Gate.fetc_site, gate(navi, false)); var rebi = base; rebi.host = "attacker.example"; try tszz.expectEqual(Gate.host, gate(rebi, false)); }
test "pathOnly strips query" { try tszz.expectEqualStrings("/css/base.css", http.pathOnly("/css/base.css?v=2")); try tszz.expectEqualStrings("/ping", http.pathOnly("/ping")); }
test "queryValue extracts params" { try tszz.expectEqualStrings("E:\\00_modules", http.querValu("path=E:\\00_modules&x=1", "path").?); try tszz.expect(http.querValu("path=x", "missing") == null); }
test "urlDecode handles percent and plus" { var bufz: [64]u8 = undefined; try tszz.expectEqualStrings("E:\\my dir", http.urlzDeco(&bufz, "E%3A%5Cmy+dir")); }
test "mimeFor known types" { try tszz.expectEqualStrings("text/css; charset=utf-8", http.mimeFind("/css/base.css")); try tszz.expectEqualStrings("application/javascript; charset=utf-8", http.mimeFind("/js/x.js")); try tszz.expectEqualStrings("image/x-icon", http.mimeFind("/favicon.ico")); }
test "safeStaticPath rejects traversal, encodings and streams" { const allo = tszz.allocator; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const aggg = aren.allocator(); const root = "E:\\app"; try tszz.expect(http.statPathSafe(aggg, root, "/../../secret.txt") == null); try tszz.expect(http.statPathSafe(aggg, root, "/..%2fsecret") == null); try tszz.expect(http.statPathSafe(aggg, root, "/index.html::$DATA") == null); try tszz.expect(http.statPathSafe(aggg, root, "/js\\..\\x") == null); try tszz.expect(http.statPathSafe(aggg, root, "/index.html") != null); try tszz.expect(http.statPathSafe(aggg, root, "/build.zig") == null); try tszz.expect(http.statPathSafe(aggg, root, "/aa-auto-task.json") == null); try tszz.expect(http.statPathSafe(aggg, root, "/do-docs-deve/x.html") == null); try tszz.expect(http.statPathSafe(aggg, root, "/js-x.js") != null); }
test "etagOf is stable and quoted" { var buf1: [24]u8 = undefined; var buf2: [24]u8 = undefined; const etg1 = http.etagHash(&buf1, "abc"); try tszz.expectEqualStrings(etg1, http.etagHash(&buf2, "abc")); try tszz.expect(etg1[0] == '"' and etg1[etg1.len - 1] == '"'); }
